mapper.select:
select sd.id, sdd.id as detailId, sd.code, sd.shop_name as shopName, sdd.sku_no as skuNo, sdd.product_name as productName, sdd.variant_property as variantProperty, sdd.is_urgent as isUrgent, sd.is_first_mass_product as isFirstMassProduct, sdd.plan_delivery_date as planDeliveryDate, sdd.plan_stock_qty as planStockQty, sdd.dest_warehouse_name as destWarehouseName, sdd.remark as remark, sd.remark as stockReason, sd.approve_status as approveStatus, sd.invalid_status as invalidStatus, sd.approve_user_name as approveUserName, sd.approve_time as approveTime, sd.create_user_name as createUserName, sd.create_time as createTime from sales_demand sd inner join sales_demand_detail sdd on sd.id = sdd.sales_demand_id and sdd.is_deleted = false where ${params.sqlMap.default} and sd.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
sd.create_time desc

select sd.id, sd.code, sd.shop_name as shopName, sdd.sku_no as skuNo, sdd.product_name as productName, sdd.is_urgent as isUrgent, case sd.is_first_mass_product when true then '是' when false then '否' end as isFirstMassProduct, sdd.plan_delivery_date as planDeliveryDate, sdd.plan_stock_qty as planStockQty, sdd.dest_warehouse_name as destWarehouseName, sdd.remark as remark, sd.remark as stockReason, case sd.approve_status when 'waitSubmit' then '待提交' when 'approveIng' then '审核中' when 'reject' then '审核不通过' when 'approve' then '已审核' end as approveStatusName, case sd.invalid_status when false then '未作废' when true then '已作废' end as invalidStatusName, sd.approve_user_name as approveUserName, sd.approve_time as approveTime, sd.create_user_name as createUserName, sd.create_time as createTime from sales_demand sd left join sales_demand_detail sdd on sd.id = sdd.sales_demand_id and sdd.is_deleted = false where ${params.sqlMap.default} and sd.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
sd.create_time desc

select count(distinct sd.id) from sales_demand sd left join sales_demand_detail sdd on sd.id = sdd.sales_demand_id and sdd.is_deleted = false
sd.is_deleted = false
and sd.approve_status in
#{item}
${params.permissionSql}
